{"kind":"stack","id":"magnets-stack","title":"Magnetic materials","theme":{"background":"#fdf6e3","foreground":"#1f2937","font":"Arial, sans-serif"}}
{"kind":"card","card":{"id":"c1","kind":"flash","elements":[{"type":"text","id":"c1-term","content":"Magnetic material"},{"type":"text","id":"c1-def","content":"A material that is pulled towards a magnet. Iron, steel, nickel and cobalt are magnetic."},{"type":"button","id":"c1-next","label":"Next Card","actions":[{"type":"goto","cardId":"c2"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c2","kind":"flash","elements":[{"type":"text","id":"c2-term","content":"Non-magnetic material"},{"type":"text","id":"c2-def","content":"A material that a magnet does not pull towards it. Wood, plastic, glass and paper are non-magnetic."},{"type":"button","id":"c2-next","label":"Next Card","actions":[{"type":"goto","cardId":"c3"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c3","kind":"quiz","elements":[{"type":"image","picto":"magnet"},{"type":"text","id":"c3-q","content":"Which of these materials is attracted to a magnet?"},{"type":"button","id":"c3-a","label":"Wood","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c4"}]},{"type":"button","id":"c3-b","label":"Iron nail","actions":[{"type":"score","delta":1},{"type":"sound","sound":"cheer"},{"type":"goto","cardId":"c4"}]},{"type":"button","id":"c3-c","label":"Plastic cup","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c4"}]},{"type":"button","id":"c3-d","label":"Glass jar","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c4"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c4","kind":"quiz","elements":[{"type":"text","id":"c4-q","content":"Which metal is magnetic?"},{"type":"button","id":"c4-a","label":"Copper","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c5"}]},{"type":"button","id":"c4-b","label":"Aluminium","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c5"}]},{"type":"button","id":"c4-c","label":"Steel","actions":[{"type":"score","delta":1},{"type":"sound","sound":"cheer"},{"type":"goto","cardId":"c5"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c5","kind":"quiz","elements":[{"type":"text","id":"c5-q","content":"Which of these is NOT a magnetic material?"},{"type":"button","id":"c5-a","label":"Nickel","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c6"}]},{"type":"button","id":"c5-b","label":"Cobalt","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c6"}]},{"type":"button","id":"c5-c","label":"Paper","actions":[{"type":"score","delta":1},{"type":"sound","sound":"cheer"},{"type":"goto","cardId":"c6"}]},{"type":"button","id":"c5-d","label":"Iron","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c6"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c6","kind":"story","elements":[{"type":"text","id":"c6-q","content":"You are sorting a box of objects. You find a metal spoon and a wooden spoon. Which do you test first with the magnet?"},{"type":"button","id":"c6-a","label":"The metal spoon","actions":[{"type":"goto","cardId":"c7"}]},{"type":"button","id":"c6-b","label":"The wooden spoon","actions":[{"type":"goto","cardId":"c8"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c7","kind":"story","elements":[{"type":"text","id":"c7-t","content":"The magnet sticks to the metal spoon. You have found a magnetic material. Well done for testing carefully."},{"type":"button","id":"c7-next","label":"Continue","actions":[{"type":"goto","cardId":"c9"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c8","kind":"story","elements":[{"type":"text","id":"c8-t","content":"The magnet does not stick to the wooden spoon. Wood is non-magnetic. Testing the other spoon next will help you compare them."},{"type":"button","id":"c8-next","label":"Continue","actions":[{"type":"goto","cardId":"c9"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c9","kind":"quiz","elements":[{"type":"text","id":"c9-q","content":"Which material would a magnet pull towards it?"},{"type":"button","id":"c9-a","label":"Rubber","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c10"}]},{"type":"button","id":"c9-b","label":"Nickel coin","actions":[{"type":"score","delta":1},{"type":"sound","sound":"cheer"},{"type":"goto","cardId":"c10"}]},{"type":"button","id":"c9-c","label":"Cotton wool","actions":[{"type":"score","delta":0},{"type":"sound","sound":"buzz"},{"type":"goto","cardId":"c10"}]}],"actions":[]}}
{"kind":"card","card":{"id":"c10","kind":"end","elements":[{"type":"text","id":"c10-h","content":"You finished the magnets quiz!"},{"type":"text","id":"c10-m","content":"You now know which everyday materials are magnetic and which are not. Keep testing objects around you."}],"actions":[]}}
